// Only the selected S4 required trainers native battle presentation/engine wait. Never persistence.
export async function waitS4GameplayBattle(play,signal){if(!(signal instanceof AbortSignal))throw Error('INVALID_S4_GAMEPLAY_LIFECYCLE');const cancelled=()=>Object.assign(Error('S4_GAMEPLAY_NATIVE_DISPOSED'),{code:'S4_GAMEPLAY_NATIVE_DISPOSED'});if(signal.aborted)throw cancelled();let cancel;try{return await new Promise((resolve,reject)=>{cancel=()=>reject(cancelled());signal.addEventListener('abort',cancel,{once:true});Promise.resolve().then(()=>{if(signal.aborted)throw cancelled();return play()}).then(resolve,reject)})}finally{signal.removeEventListener('abort',cancel)}}
